def facts(applicant):
    # Work out each fact once per applicant, not once per scheme.
    kids = [m for m in applicant['household'] if m['relation'] in ('son', 'daughter')]
    return {
        'employment_status': applicant['employment_status'],
        'income': applicant['monthly_income'],
        'size': 1 + len(applicant['household']),        # the applicant counts too
        'school_child': any(7 <= m['age'] <= 16 for m in kids),
    }

# One small rule per criterion key: (facts, value) -> bool.
RULES = {
    'employment_status': lambda f, v: f['employment_status'] == v,
    'max_monthly_income': lambda f, v: f['income'] <= v,
    'has_child_in_school': lambda f, v: f['school_child'] == v,
    'min_household_size': lambda f, v: f['size'] >= v,
}

def solution(applicants, schemes):
    result = {}
    for a in applicants:
        f = facts(a)
        ok = [s['id'] for s in schemes
              if all(RULES[key](f, value) for key, value in s['criteria'].items())]
        result[a['id']] = sorted(ok)
    return result

