def solution(applicants, schemes):
    # First collect every (applicant, scheme) pair that passes, re-reading the
    # household for every check. Then, for each applicant, scan the whole pair
    # list again to pick out its schemes: O(applicants x pairs).
    pairs = []
    for s in schemes:
        for a in applicants:
            ok = True
            for key in s['criteria']:
                v = s['criteria'][key]
                if key == 'employment_status' and a['employment_status'] != v:
                    ok = False
                if key == 'max_monthly_income' and a['monthly_income'] > v:
                    ok = False
                if key == 'min_household_size' and len(a['household']) + 1 < v:
                    ok = False
                if key == 'has_child_in_school':
                    has = False
                    for m in a['household']:
                        if (m['relation'] == 'son' or m['relation'] == 'daughter') and m['age'] >= 7 and m['age'] <= 16:
                            has = True
                    if has != v:
                        ok = False
            if ok:
                pairs.append((a['id'], s['id']))
    result = {}
    for a in applicants:
        mine = []
        for aid, sid in pairs:
            if aid == a['id']:
                mine.append(sid)
        mine.sort()
        result[a['id']] = mine
    return result
